const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const rawBody = item.json.rawBody || JSON.stringify(item.json.body || {});

const eventId = headers['x-event-id'];
const timestampStr = headers['x-timestamp'];
const signature = headers['x-signature'];

if (!signature || !timestampStr || !eventId) {
  throw new Error('Missing required webhook verification headers');
}

const timestamp = parseInt(timestampStr, 10);
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - timestamp) > 300) {
  throw new Error('Timestamp skew exceeds 300 seconds');
}

const secret = $env.N8N_EVENT_SIGNING_SECRET || '';
const canonical = timestampStr + '.' + rawBody;
const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');

if (signature !== expectedSig) {
  throw new Error('Invalid X-Signature');
}

const parsed = typeof item.json.body === 'object' ? item.json.body : JSON.parse(rawBody);
const payload = parsed.payload || {};
const taskId = payload.task_id || parsed.aggregate_id;

return [{
  json: {
    event_id: eventId,
    event_type: parsed.event_type,
    tenant_id: parsed.tenant_id,
    task_id: taskId,
    lead_id: payload.lead_id,
    retry_count: payload.retry_count || 0
  }
}];

const event = $('Verify Dispatcher Signature').item.json;
const sendResult = $input.first().json || {};
const statusCode = sendResult.statusCode || (sendResult.error ? sendResult.error.statusCode : 200);
const errorObj = sendResult.error || {};
const errorCode = (errorObj.error && errorObj.error.code) || errorObj.code || 'unknown';

let outcome = 'unknown';
let recordPayload = null;
let notificationPayload = null;

if (statusCode === 200) {
  outcome = 'sent';
  recordPayload = {
    status: 'sent',
    task_status: 'done',
    message_id: sendResult.data ? sendResult.data.message_id : null,
    note: 'Sent automated WhatsApp follow-up.'
  };
} else if (statusCode === 202) {
  outcome = 'quiet_hours';
  // Quiet hours already rescheduled by backend; nothing more to record
} else if (errorCode === 'approval_required') {
  outcome = 'approval_required';
  recordPayload = {
    status: 'needs_approval',
    error_code: 'approval_required'
  };
} else if (errorCode === 'opted_out') {
  outcome = 'opted_out';
  recordPayload = {
    status: 'skipped',
    task_status: 'cancelled',
    error_code: 'opted_out',
    note: 'Lead opted out; follow-up cancelled.'
  };
} else if (errorCode === 'window_closed') {
  outcome = 'window_closed';
  recordPayload = {
    status: 'skipped',
    error_code: 'window_closed',
    note: '24-hour reply window closed. Manual template required.'
  };
} else if (errorCode === 'task_not_open' || errorCode === 'task_inactive' || errorCode === 'lead_closed') {
  outcome = 'task_not_open';
  recordPayload = {
    status: 'skipped',
    error_code: errorCode,
    note: 'Task or lead is inactive; skipped.'
  };
} else {
  outcome = 'failed';
  const isFirstFailure = (event.retry_count || 0) < 1;
  recordPayload = {
    status: 'failed',
    retryable: isFirstFailure,
    error_code: errorCode
  };
}

return [{
  json: {
    tenant_id: event.tenant_id,
    task_id: event.task_id,
    event_id: event.event_id,
    outcome: outcome,
    recordPayload: recordPayload,
    notificationPayload: notificationPayload
  }
}];
